'use strict';const D=JSON.parse(document.getElementById('data').textContent),R=D.formaciones,$=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const norm=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const fields={pais:'pais',idioma:'idiomas',modo:'modalidad',ambito:'ambito',perfil:'perfiles',tipo:'tipo',internacional:'internacional',becas:'becas_estado',acuerdo:'acuerdo_espana'};let selected=R;
for(const [id,key]of Object.entries(fields)){let vals=[...new Set(R.flatMap(r=>Array.isArray(r[key])?r[key]:[r[key]]))].filter(Boolean).sort((a,b)=>a.localeCompare(b,'es'));$(id).innerHTML='<option value="">Todas las opciones</option>'+vals.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('');$(id).addEventListener('change',render)}
$('stats').innerHTML=`<span>${R.length} fichas</span><span>${D.estadisticas.paises_con_fichas} países</span><span>${D.estadisticas.idioma_documentado} con idioma documentado</span><span>${D.estadisticas.modalidad_documentada} con modalidad documentada</span>`;
const fact=(label,val)=>`<div><dt>${label}</dt><dd>${esc(val)}</dd></div>`;
function render(){const terms=norm($('q').value).split(/\s+/).filter(Boolean);selected=R.filter(r=>terms.every(t=>norm([r.nombre,r.institucion,r.cobertura,r.pais,...r.perfiles].join(' ')).includes(t))&&Object.entries(fields).every(([id,key])=>!$(id).value||(Array.isArray(r[key])?r[key].includes($(id).value):r[key]===$(id).value)));$('count').textContent=`${selected.length} de ${R.length} formaciones · ${new Set(selected.map(r=>r.pais)).size} países`;$('cards').innerHTML=selected.length?selected.map(r=>`<article class="card"><div class="badges"><span class="badge">${esc(r.pais)}</span><span class="badge">${esc(r.tipo)}</span></div><h2>${esc(r.nombre)}</h2><div class="institution">${esc(r.institucion)}</div><p>${esc(r.cobertura)}</p><dl class="facts">${fact('Idioma de docencia',r.idiomas.join(' / ')||'Por confirmar con la institución')}${fact('Modalidad',r.modalidad)}${fact('Admisión internacional',r.internacional)}${fact('Ayudas',r.becas_estado)}${fact('Convenio / vía en España',r.acuerdo_espana)}</dl><a href="${esc(r.fuente)}" target="_blank" rel="noopener noreferrer">Consultar fuente oficial ↗</a><details><summary>Acceso, reconocimiento, ayudas y fuentes</summary><p><strong>Créditos / duración:</strong> ${esc(r.creditos)}</p><p><strong>Acceso desde otros países:</strong> ${esc(r.admision_internacional)}</p><p><strong>Reconocimiento en origen:</strong> ${esc(r.reconocimiento)}</p><p><strong>Convenio con España:</strong> ${esc(r.condiciones_convenio)}</p><p><strong>Aplicación a este título:</strong> ${esc(r.aplicacion_al_titulo)}</p><p><strong>Vía de reconocimiento en España:</strong> ${esc(r.via_espana)}</p><p><strong>Otros países europeos:</strong> ${esc(r.acuerdo_europa)}</p><p><strong>Reconocimiento europeo:</strong> ${esc(r.reconocimiento_europeo)}</p><p><strong>Habilitación profesional:</strong> ${esc(r.habilitacion)}</p><p><strong>Becas, financiación y condiciones:</strong> ${esc(r.becas)}</p><p><strong>Coste:</strong> ${esc(r.coste)}</p><p><strong>Edición y disponibilidad:</strong> ${esc(r.vigencia)}</p><p><strong>Áreas documentadas:</strong> ${esc(r.perfiles.join(' · '))}</p><ul>${r.fuentes.map(f=>`<li><a href="${esc(f.url)}" target="_blank" rel="noopener noreferrer">${esc(f.concepto)}</a></li>`).join('')}</ul><p class="note">Consulta: ${esc(r.consulta)} · ${esc(r.id)}. Comprueba la convocatoria antes de solicitar plaza.</p></details></article>`).join(''):'<p class="empty">No hay resultados para esta combinación. Prueba a quitar un filtro.</p>'}
$('q').addEventListener('input',render);$('reset').addEventListener('click',()=>{$('q').value='';Object.keys(fields).forEach(id=>$(id).value='');render()});function download(content,type,name){const u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};$('json').addEventListener('click',()=>download(JSON.stringify(D,null,2),'application/json','FAND_Formaciones_Oficiales.json'));$('csv').addEventListener('click',()=>{const cols=['nombre','institucion','pais','tipo','idiomas','modalidad','ambito','perfiles','creditos','internacional','admision_internacional','reconocimiento','reconocimiento_europeo','habilitacion','acuerdo_espana','condiciones_convenio','aplicacion_al_titulo','via_espana','acuerdo_europa','convenio_url','becas_estado','becas','vigencia','fuente','consulta'];const cell=v=>'"'+String(Array.isArray(v)?v.join(' / '):v??'').replace(/"/g,'""')+'"';download('\ufeff'+[cols.map(cell).join(';'),...selected.map(r=>cols.map(k=>cell(r[k])).join(';'))].join('\r\n'),'text/csv;charset=utf-8','FAND_Formaciones_Seleccion.csv')});
$('agreements').innerHTML=D.convenios_espana.map(a=>`<tr><td style="padding:10px;border-bottom:1px solid #dae5e6">${esc(a.pais)}</td><td style="padding:10px;border-bottom:1px solid #dae5e6">${esc(a.nota)}</td><td style="padding:10px;border-bottom:1px solid #dae5e6"><a href="${esc(a.url)}" target="_blank" rel="noopener noreferrer">Texto del acuerdo</a></td></tr>`).join('');$('recognition-guide').innerHTML=D.reconocimiento_guia.map(g=>`<p><strong>${esc(g.concepto)}:</strong> ${esc(g.detalle)} <a href="${esc(g.fuente)}" target="_blank" rel="noopener noreferrer">Fuente oficial ↗</a></p>`).join('');$('framework').innerHTML=D.marco_europeo.map(f=>`<p><a href="${esc(f.url)}" target="_blank" rel="noopener noreferrer">${esc(f.nombre)}</a> · ${esc(f.nota)}</p>`).join('');$('coverage').innerHTML=`<div><h3>Países con fichas (Europa y ampliación)</h3><p>${esc(D.cobertura_paises.con_fichas.join(' · '))}</p></div><div><h3>Búsqueda sin ficha incorporada</h3><p>${esc(D.cobertura_paises.buscados_sin_ficha_incorporada.join(' · '))}</p><p>${esc(D.cobertura_paises.nota)}</p></div><p>${esc(D.cobertura_paises.otras_zonas_pendientes)}</p>`;$('candidates').innerHTML=D.candidatos_no_incorporados.map(c=>`<p><a href="${esc(c.fuente)}" target="_blank" rel="noopener noreferrer">${esc(c.programa)}</a> · ${esc(c.motivo)}</p>`).join('');$('method').innerHTML=Object.entries(D.metodologia).map(([k,v])=>`<p><strong>${esc(k)}:</strong> ${esc(v)}</p>`).join('');render();
</script></body></html>